(PE, 130, "The value of (2/3)^{5} × (2/3)^{0} × (2/3)^{−5} is", ["1", "0", "−1", "None of these"], "A", ["Same base, so add the powers: 5 + 0 + (−5) = 0.", "(2/3)^{0} = 1."]),
