(PE, 133, "The value of (x/y)^{1/2} · (y/x)^{1/2} is", ["0", "1/4", "1", "−1"], "C", ["(x/y)^{1/2} · (y/x)^{1/2} = (x/y × y/x)^{1/2}.", "= 1^{1/2} = 1."]),
