(PE, 136, "The value of (64/27)^{1/3} is", ["4/3", "1/(3√3)", "3/4", "None of these"], "A", ["64 = 4^{3} and 27 = 3^{3}.", "So (64/27)^{1/3} = 4/3."]),
(PE, 137, "The value of [(1/4)^{2} − (1/4)^{3}] × 2^{5} is", ["1", "2", "3/2", "4"], "C", ["(1/4)^{2} = 1/16 and (1/4)^{3} = 1/64, so the bracket = 4/64 − 1/64 = 3/64.", "3/64 × 32 = 3/2."]),
