(PE, 145, "If (a/b)^{x−1} = (b/a)^{x−3}, then the value of x is", ["1/2", "1", "2", "7/2"], "C", ["(b/a)^{x−3} = (a/b)^{3−x}.", "So x − 1 = 3 − x, giving 2x = 4 and x = 2."]),
(PE, 146, "If 2^{n+4} − 2^{n+2} = 3, then n is equal to", ["0", "2", "−1", "−2"], "D", ["2^{n+4} − 2^{n+2} = 2^{n+2}(2^{2} − 1) = 3 × 2^{n+2}.", "So 2^{n+2} = 1 = 2^{0}.", "n + 2 = 0, so n = −2."]),
