(PE, 161, "If 4^{x+3} = 8^{x−1}, then the value of x is", ["10", "8", "9", "3"], "C", ["4^{x+3} = 2^{2x+6} and 8^{x−1} = 2^{3x−3}.", "2x + 6 = 3x − 3, so x = 9."]),

