(LH, 191, "The HCF of 2 and 3 is", ["6", "2", "3", "1"], "D", ["2 and 3 have no common factor other than 1.", "So HCF = 1."]),
(LH, 192, "The HCF of 2 numbers is 12 and their difference is also 12. Then the numbers are", ["84, 96", "12, 36", "80, 90", "None of these"], "A", ["84 = 12 × 7 and 96 = 12 × 8, where 7 and 8 are co-prime, so their HCF is 12; they also differ by 12.", "12 and 36 differ by 24, and the HCF of 80 and 90 is 10."]),
(LH, 193, "If the HCF of p and q is 3 and their LCM is 6, then p × q =", ["18", "6", "3", "0"], "A", ["Product of two numbers = HCF × LCM.", "p × q = 3 × 6 = 18."]),
(LH, 194, "The product of two numbers is 4107. If the H.C.F. of these numbers is 37, then the greater number is", ["107", "101", "111", "185"], "C", ["Let the numbers be 37a and 37b with a, b co-prime: 37 × 37 × ab = 4107, so ab = 3.", "So a = 1 and b = 3, and the numbers are 37 and 111.", "The greater number is 111."]),
(LH, 195, "If H.C.F.(a, b) = 12 and a × b = 1800, then L.C.M.(a, b) =", ["3600", "900", "150", "90"], "C", ["LCM = product ÷ HCF.", "1800 ÷ 12 = 150."]),
(LH, 196, "The HCF of 12 and 15 is", ["2", "3", "5", "1"], "B", ["12 = 2^{2} × 3 and 15 = 3 × 5.", "The common factor is 3, so HCF = 3."]),
(LH, 197, "The LCM of 8 and 12 is", ["24", "12", "8", "4"], "A", ["8 = 2^{3} and 12 = 2^{2} × 3.", "LCM = 2^{3} × 3 = 24."]),
(LH, 198, "If the HCF of two numbers is 2 and their LCM is 12, then the product of the two numbers is", ["24", "48", "12", "None of these"], "A", ["Product = HCF × LCM = 2 × 12 = 24."]),
(LH, 199, "The HCF of 2 consecutive numbers is", ["1", "2", "3", "0"], "A", ["Two consecutive numbers have no common factor other than 1.", "So their HCF is 1."]),
(LH, 200, "The LCM of 4 and 9 is", ["1", "4", "9", "36"], "D", ["4 and 9 have no common factor, so LCM = 4 × 9 = 36."]),
(LH, 201, "The HCF (Highest Common Factor) of 24 and 36 is", ["72", "6", "8", "12"], "D", ["24 = 2^{3} × 3 and 36 = 2^{2} × 3^{2}.", "HCF = 2^{2} × 3 = 12."]),
(LH, 202, "The LCM (Lowest Common Multiple) of 24 and 90 is", ["90", "360", "6", "180"], "B", ["24 = 2^{3} × 3 and 90 = 2 × 3^{2} × 5.", "LCM = 2^{3} × 3^{2} × 5 = 360."]),
(LH, 203, "The LCM of 6 and 18 is", ["24", "6", "18", "None of these"], "C", ["18 is a multiple of 6, so LCM = 18."]),
(LH, 204, "What is the H.C.F. of 1/5, 2/7 and 1/11?", ["1/385", "0", "1/15", "5/22"], "A", ["HCF of fractions = HCF of numerators ÷ LCM of denominators.", "HCF(1, 2, 1) = 1 and LCM(5, 7, 11) = 385, so HCF = 1/385."]),
(LH, 205, "The HCF of 30 and 42 is", ["6", "210", "90", "3"], "A", ["30 = 2 × 3 × 5 and 42 = 2 × 3 × 7.", "HCF = 2 × 3 = 6."]),
(LH, 206, "The HCF of two consecutive even numbers is", ["1", "2", "4", "None of these"], "B", ["Consecutive even numbers are 2n and 2(n + 1).", "n and n + 1 are co-prime, so the HCF is 2."]),
(LH, 207, "Three numbers are in the ratio 1 : 2 : 3 and their H.C.F. is 12. The numbers are", ["4, 8, 12", "5, 10, 15", "10, 20, 30", "None of these"], "D", ["The numbers are 12 × 1, 12 × 2 and 12 × 3 = 12, 24 and 36.", "This set is not among the options, so the answer is None of these."]),
(LH, 208, "The HCF of 6, 72 and 120 is", ["2", "3", "6", "120"], "C", ["6 divides both 72 and 120.", "So the HCF of 6, 72 and 120 is 6."]),
(LH, 209, "The LCM of 96 and 404 is", ["9690", "96 × 404", "9696", "96"], "C", ["96 = 2^{5} × 3 and 404 = 2^{2} × 101.", "LCM = 2^{5} × 3 × 101 = 9696."]),
(LH, 210, "The HCF of 21 and 35 is", ["21 × 35", "35", "21", "7"], "D", ["21 = 3 × 7 and 35 = 5 × 7.", "HCF = 7."]),
(LH, 212, "The H.C.F. of 4 × 27 × 3125, 8 × 9 × 25 × 7 and 16 × 81 × 5 × 11 × 49 is", ["180", "360", "540", "1260"], "A", ["In prime factors: 2^{2} × 3^{3} × 5^{5}, 2^{3} × 3^{2} × 5^{2} × 7 and 2^{4} × 3^{4} × 5 × 7^{2} × 11.", "HCF takes the lowest powers of the common primes: 2^{2} × 3^{2} × 5 = 180."]),
(LH, 213, "Find the lowest common multiple of 24, 36 and 40.", ["120", "240", "360", "480"], "C", ["24 = 2^{3} × 3, 36 = 2^{2} × 3^{2} and 40 = 2^{3} × 5.", "LCM = 2^{3} × 3^{2} × 5 = 360."]),
(LH, 214, "Two brands of chocolates are available in packs of 24 and 15 respectively. If I need to buy an equal number of chocolates of both kinds, what is the least number of boxes of each kind I would need to buy?", ["5, 6", "5, 8", "5, 11", "12, 14"], "B", ["The least equal number of chocolates = LCM of 24 and 15 = 120.", "Boxes: 120 ÷ 24 = 5 of the first kind and 120 ÷ 15 = 8 of the second."]),
(LH, 215, "Two numbers are in the ratio 15 : 11. If their HCF is 13, the numbers will be", ["195 and 143", "190 and 140", "185 and 163", "185 and 143"], "A", ["The numbers are 15 × 13 and 11 × 13.", "= 195 and 143."]),
(LH, 216, "Find the least number which when divided by 6, 7, 8, 9 and 10 leaves remainder 1.", ["2531", "2521", "5041", "7561"], "B", ["LCM of 6, 7, 8, 9 and 10 = 2520.", "Required number = 2520 + 1 = 2521."]),
(LH, 217, "The number of factors of 1080 is", ["32", "28", "24", "36"], "A", ["1080 = 2^{3} × 3^{3} × 5.", "Number of factors = (3 + 1)(3 + 1)(1 + 1) = 32."]),
(LH, 218, "If x and y are two co-primes, then their L.C.M. is", ["xy", "x + y", "x", "1"], "A", ["Co-prime numbers have HCF 1.", "LCM = product ÷ HCF = xy."]),
(LH, 219, "The sum of two numbers is 95. If one exceeds the other by 15, then the two numbers are", ["80, 15", "40, 55", "50, 45", "None of these"], "B", ["Larger = (95 + 15) ÷ 2 = 55 and smaller = (95 − 15) ÷ 2 = 40.", "So the numbers are 40 and 55."], "APSSB UDC 2019"),
(LH, 220, "The greatest value that must be given to x so that the number 7713x8 is divisible by 4 is", ["1", "6", "8", "7"], "C", ["A number is divisible by 4 when its last two digits form a multiple of 4, so x8 must be a multiple of 4.", "This works for x = 0, 2, 4, 6 and 8, so the greatest value is 8."]),
(LH, 221, "If the H.C.F. and L.C.M. of two terms a and b are x and y respectively, and a + b = x + y, then x^{2} + y^{2} =", ["a^{2} − b^{2}", "2a^{2} + b^{2}", "a^{2} + b^{2}", "a^{2} − 2b^{2}"], "C", ["HCF × LCM = product, so xy = ab.", "x^{2} + y^{2} = (x + y)^{2} − 2xy = (a + b)^{2} − 2ab = a^{2} + b^{2}."]),
(LH, 222, "If the LCM and HCF of two numbers 64 and x are 160 and 16 respectively, then the value of x is", ["40", "16", "80", "36"], "A", ["64 × x = LCM × HCF = 160 × 16 = 2560.", "x = 2560 ÷ 64 = 40."]),
(LH, 223, "The HCF of 1/2 and 1/3 is", ["1", "1/6", "6", "1/5"], "B", ["HCF of fractions = HCF of numerators ÷ LCM of denominators.", "HCF(1, 1) = 1 and LCM(2, 3) = 6, so HCF = 1/6."]),
(LH, 224, "The smallest number which when divided by 5 or 11 leaves a remainder of 4 is", ["59", "49", "124", "69"], "A", ["LCM of 5 and 11 = 55.", "Numbers of the form 55k + 4 work; leaving aside 4 itself, the smallest is 55 + 4 = 59."]),
(LH, 225, "The greatest number which divides 68, 140 and 248 leaving the same remainder in each case is", ["36", "18", "72", "108"], "A", ["Take the differences: 140 − 68 = 72, 248 − 140 = 108 and 248 − 68 = 180.", "HCF of 72, 108 and 180 = 36."]),

